
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_hyb_gga_xc_hpbeint_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("hyb_gga_xc_hpbeint", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-3.608097799190955e+00, -3.538262082291459e+00, -3.440435261852962e+00, -3.304987429344493e+00, -3.120575437046278e+00, -2.875501169330756e+00, -2.560971452810481e+00, -2.177167008665780e+00, -1.742037882799109e+00, -1.296528430960748e+00, -8.800862661872337e-01, -6.215011758824692e-01, -5.452354614007943e-01, -4.432948679071655e-01, -3.154052490528818e-01, -1.980687397507427e-01, -1.096853954563585e-01, -4.125254327296382e-02, -9.009932918129517e-03, -1.013501790606539e-03]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


